// Opening facts (DECISIONS #130, the user's pick "B + C"): each opening's win rates and special features, from the
// app's own explorer data (600,000 Lichess rated games, January 2025, players 1200-2200, CC0), measured at the move
// that names the opening. The numbers are generated by test/opening-stats.test.ts (OPENING_STATS=1) into
// src/content/opening-stats.json; the style and level tags below are our own guidance, not data.
import STATS from "../content/opening-stats.json";

/** The number of plies that name each opening (1.e4 c5 = 2 for the Sicilian). */
export const NAMED_AT: Record<string, number> = {
  italian: 5, london: 3, qg: 3, fourknights: 6, e5: 2, sicilian: 2, carokann: 2, qgd: 4, slav: 4, kid: 4,
  ruy: 5, vienna: 3, scotch: 5, french: 2, scandi: 2, nimzo: 6, dutch: 2, english: 1, catalan: 5, pirc: 6, alekhine: 2, grunfeld: 6, qid: 6,
  reti: 3, petroff: 4, modern: 2, evans: 7, twoknights: 6, benoni: 4, philidor: 4, kia: 3, bogo: 6, dragon: 10, trompowsky: 3,
};

export type Style = "classical" | "system" | "simple" | "sharp" | "solid" | "attacking" | "open" | "positional" | "flexible" | "tricky" | "dynamic" | "gambit";
export type Level = 1 | 2 | 3;
export const TAGS: Record<string, [Style, Level]> = {
  italian: ["classical", 1], london: ["system", 1], qg: ["classical", 2], fourknights: ["simple", 1], e5: ["classical", 1],
  sicilian: ["sharp", 3], carokann: ["solid", 2], qgd: ["solid", 2], slav: ["solid", 2], kid: ["attacking", 3], ruy: ["classical", 3],
  vienna: ["attacking", 2], scotch: ["open", 2], french: ["solid", 2], scandi: ["simple", 1], nimzo: ["positional", 3], dutch: ["attacking", 2],
  english: ["flexible", 2], catalan: ["positional", 3], pirc: ["flexible", 2], alekhine: ["tricky", 3], grunfeld: ["dynamic", 3],
  qid: ["positional", 3], reti: ["flexible", 2], petroff: ["solid", 2], modern: ["flexible", 2], evans: ["gambit", 2],
  twoknights: ["attacking", 2], benoni: ["sharp", 3], philidor: ["solid", 1], kia: ["system", 1], bogo: ["solid", 2],
  dragon: ["sharp", 3], trompowsky: ["tricky", 2],
};

export interface OpeningStats {
  games: number; popular: number; white: number; draw: number; black: number; you: number;
  reply: { san: string; share: number } | null;
  road: { move: string; share: number; games: number } | null;   // how often club players go down the model win's road
}
export const statsFor = (id: string): OpeningStats | undefined => (STATS as Record<string, OpeningStats>)[id];
/** Under this many games the numbers are rough, and the card says so. */
export const FEW_GAMES = 500;
